"""Presentation helpers for the fictional Nexora NR-1800 router."""

# ruff: noqa: E501 -- contiguous embedded-device markup is easier to audit.

from html import escape

CSS = """
:root{--orange:#e66b19;--orange-dark:#bf4e0b;--charcoal:#292b2d;--paper:#fff;--bg:#edf0f2;--line:#cfd3d6;--text:#27292b;--muted:#687078;--green:#2b8a3e;--amber:#bd7b00;--red:#bd2c2c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px/1.45 Arial,Helvetica,sans-serif}a{color:inherit;text-decoration:none}.top{height:67px;background:var(--paper);border-top:5px solid var(--orange);border-bottom:1px solid #bbb;display:flex;align-items:center;justify-content:space-between;padding:0 25px}.brand{font-size:25px;font-weight:bold;color:var(--orange);letter-spacing:-1px}.brand small{font-size:12px;color:#555;letter-spacing:.3px;margin-left:10px;font-weight:normal}.online{color:var(--green)}.layout{display:grid;grid-template-columns:205px 1fr;min-height:calc(100vh - 67px)}nav{background:var(--charcoal);color:#ddd;padding:14px 0}nav a{display:block;padding:10px 21px;border-left:4px solid transparent}nav a:hover,nav a.active{background:#3b3e40;border-left-color:var(--orange);color:#fff}main{padding:24px;max-width:1100px;width:100%}.crumb{font-size:12px;color:var(--muted);margin-bottom:8px}h1{font-size:21px;font-weight:normal;margin:0 0 17px;padding-bottom:8px;border-bottom:2px solid var(--orange)}h2{font-size:15px;margin:0;padding:10px 13px;background:#f2f2f2;border-bottom:1px solid var(--line)}.panel{background:var(--paper);border:1px solid var(--line);margin-bottom:17px;box-shadow:0 1px 2px #0001}.inside{padding:14px}.grid{display:grid;grid-template-columns:repeat(2,minmax(250px,1fr));gap:17px}.cards{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:12px}.card{background:#fff;border:1px solid var(--line);border-top:3px solid var(--orange);padding:14px}.card b{font-size:18px;display:block;margin-top:7px}.status{color:var(--green);font-weight:bold}.warning{color:var(--amber)}.error{color:var(--red)}dl{margin:0}dt,dd{padding:7px 10px;border-bottom:1px dotted #d5d5d5}dt{float:left;clear:left;width:48%;color:#5b6165}dd{margin-left:48%;font-weight:bold}table{border-collapse:collapse;width:100%}th{background:#e8e9ea;text-align:left;color:#555}th,td{border:1px solid #d4d6d7;padding:8px}tr:nth-child(even){background:#fafafa}button,.button{border:1px solid var(--orange-dark);background:var(--orange);color:white;padding:7px 17px;font:inherit;cursor:pointer}.button.secondary,button.secondary{background:#696d70;border-color:#555}.notice{padding:10px 12px;background:#fff0e8;border:1px solid #e9b18e;color:#8a3604;margin-bottom:14px}.login-wrap{min-height:100vh;display:grid;place-items:center;background:#e8eaeb}.login{width:min(390px,calc(100% - 30px));background:#fff;border:1px solid #babec1;border-top:6px solid var(--orange);box-shadow:0 5px 20px #0002}.login-head{padding:24px 27px 14px;border-bottom:1px solid #ddd}.login-head .brand{font-size:29px}.login-head p{margin:3px 0;color:#666}.login-body{padding:20px 27px 27px}.login h1{font-size:18px}.login label{display:block;margin:10px 0 4px;color:#555}.login input{width:100%;border:1px solid #aaa;padding:9px}.login button{width:100%;margin-top:18px}.footer{font-size:11px;color:#777;text-align:center;margin-top:18px}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions form{margin:0}@media(max-width:720px){.layout{display:block}nav{display:flex;overflow:auto;padding:0}nav a{white-space:nowrap;padding:9px 12px;border-left:0;border-bottom:3px solid transparent}nav a.active{border-bottom-color:var(--orange)}main{padding:14px}.grid,.cards{grid-template-columns:1fr}.top{padding:0 14px}.brand small{display:none}}
"""


def login_page(error: bool = False) -> str:
    notice = '<div class="notice">Login failed. Check the administrator name and password.</div>' if error else ""
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Nexora NR-1800 | Administrator Login</title><style>{CSS}</style></head><body><div class="login-wrap"><section class="login"><div class="login-head"><div class="brand">Nexora</div><p><b>NR-1800</b> Wireless Router</p></div><div class="login-body"><h1>Administrator Login</h1>{notice}<form method="post" action="/login"><label for="username">User Name</label><input id="username" name="username" autocomplete="username" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required><button type="submit">Log In</button></form><div class="footer">Firmware 1.8.3 · Nexora Networks</div></div></section></div></body></html>'''


def table(rows: tuple[tuple[str, str], ...]) -> str:
    return "<dl>" + "".join(f"<dt>{escape(key)}</dt><dd>{escape(value)}</dd>" for key, value in rows) + "</dl>"


def device_table(rows: tuple[tuple[str, ...], ...]) -> str:
    header, *items = rows
    return "<table><thead><tr>" + "".join(f"<th>{escape(value)}</th>" for value in header) + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{escape(value)}</td>" for value in row) + "</tr>" for row in items) + "</tbody></table>"


def shell(title: str, active: str, body: str, system_time: str) -> str:
    links = (("dashboard", "Dashboard"), ("internet", "Internet"), ("lan", "LAN"), ("wifi", "Wi-Fi"), ("dhcp", "DHCP"), ("clients", "Connected Devices"), ("system", "System"), ("firmware", "Firmware"), ("logs", "Logs"))
    navigation = "".join(f'<a class="{"active" if key == active else ""}" href="/{key}">{label}</a>' for key, label in links)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{escape(title)} | Nexora NR-1800</title><style>{CSS}</style></head><body><header class="top"><div class="brand">Nexora <small>NR-1800 WIRELESS ROUTER</small></div><div><span class="online">● Connected</span> &nbsp; {escape(system_time)}</div></header><div class="layout"><nav>{navigation}<a href="/logout">Logout</a></nav><main><div class="crumb">NEXORA-GW / {escape(title)}</div>{body}</main></div></body></html>'''
